function openBorrow(toolId=null){const selected=toolId&&tool(toolId);if(selected&&!borrowerGroupEnabled(selected)){toast('This equipment group is disabled for borrower selection. Contact an Administrator.');return}if(!S.staff.length){toast('Add staff names in Staff & settings first.');go('settings');return}resetBorrow();if(toolId){const t=tool(toolId);if(t){id('borrow-type').value=t.type;toolOptions();id('borrow-tool').value=t.id;fillCal();loadBorrowEquipmentDetails()}}id('borrow-dialog').showModal()}
