function openCalibration(tid){let t=tool(tid),c=cal(tid);if(!t)return;id('cal-tool-id').value=tid;id('cal-tool-label').textContent=`${t.id} · ${t.group} · ${t.size}${t.unit?' '+t.unit:''}`;id('cal-cert').value=c.certificate||`CAL-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${t.id}-${Math.random().toString(36).slice(2,6).toUpperCase()}`;id('cal-due').value=c.dueDate||'2027-12-30';id('cal-actor').textContent=currentUser?.name||'';clearErr('cal-error');id('calibration-dialog').showModal()}
function openReturn(loanId){let l=S.loans.find(x=>x.loanId===loanId);if(!l)return;id('return-form').reset();id('returned-at').value=localInput();id('return-actor').textContent=currentUser?.name||'';id('return-tool-label').textContent=`${l.loanId} · ${l.staff} · ${l.toolId} / ${l.gaugeSize}`;id('return-preview').classList.add('hidden');clearErr('return-error');id('return-form').dataset.loanId=loanId;id('return-dialog').showModal()}
async function photoData(file){if(!file||!file.type.startsWith('image/'))throw Error('Choose an image from the camera or photo library.');let im;try{im=await createImageBitmap(file)}catch{im=await new Promise((resolve,reject)=>{let x=new Image();x.onload=()=>resolve(x);x.onerror=()=>reject(Error('Could not read this photo.'));x.src=URL.createObjectURL(file)})}let scale=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);im.close?.();return c.toDataURL('image/jpeg',.78)}
async function uploadPhoto(f){return (await api('/api/photos',{method:'POST',body:JSON.stringify({dataUrl:await photoData(f)})})).photoId}
async function borrowSubmit(ev){ev.preventDefault();clearErr('borrow-error');let f=ev.currentTarget,tid=id('borrow-tool').value,t=tool(tid),c=cal(tid),machine=S.workCenters.find(w=>w.machine===id('borrow-machine').value),start=new Date(id('borrowed-at').value),due=new Date(id('due-at').value),file=id('borrow-photo').files[0],issueCondition=id('borrow-condition').value,issueable=['Excellent (No Wear/Oiled)','Clean & Good (Standard Condition)','Minor Wear (Slight cosmetic scuff)'];if(!t)return error('borrow-error','Select an available gauge with current calibration details.');if(!machine)return error('borrow-error','Select a machine and work center.');if(!issueable.includes(issueCondition))return error('borrow-error','A gauge needing recalibration or under investigation cannot be issued.');if(!c.certificate||c.dueDate<start.toISOString().slice(0,10))return error('borrow-error','This gauge does not have a current calibration certificate.');if(!(due>start))return error('borrow-error','Expected return must be after borrow time.');if(!file)return error('borrow-error','A phone camera size photo is required.');if(!id('borrow-verified').checked)return error('borrow-error','Confirm the selected gauge size matches the photo.');let b=$('button[type=submit]',f);b.disabled=true;b.textContent='Saving…';try{let photoId=await uploadPhoto(file),r=await api('/api/borrow',{method:'POST',body:JSON.stringify({toolId:tid,staff:id('borrow-staff').value,jobOrder:id('borrow-jo').value.trim(),drawing:id('borrow-drawing').value.trim(),machine:machine.machine,workCenter:machine.workCenter,borrowedAt:start.toISOString(),dueAt:due.toISOString(),condition:issueCondition,notes:id('borrow-notes').value.trim(),photoId})});Object.assign(S,r.state);id('borrow-dialog').close();drawAll();toast('Borrow validated and recorded.');checkNotifications()}catch(e){error('borrow-error',e.message)}finally{b.disabled=false;b.textContent='Validate & issue gauge'}}
async function returnSubmit(ev){ev.preventDefault();clearErr('return-error');let f=ev.currentTarget,l=S.loans.find(x=>x.loanId===f.dataset.loanId),file=id('return-photo').files[0],when=new Date(id('returned-at').value),physicalCondition=id('return-physical-condition').value;if(!l||!active(l))return error('return-error','Loan is already closed or cannot be found.');if(!physicalCondition)return error('return-error','Select the physical condition observed at return.');if(!file)return error('return-error','A return photo is required.');if(!id('return-condition-ok').checked)return error('return-error','Confirm size and condition were checked.');if(when<new Date(l.borrowedAt))return error('return-error','Return time cannot be before the borrow time.');let b=$('button[type=submit]',f);b.disabled=true;try{let photoId=await uploadPhoto(file),r=await api('/api/return',{method:'POST',body:JSON.stringify({loanId:l.loanId,returnedAt:when.toISOString(),physicalCondition,conditionOK:true,notes:id('return-notes').value.trim(),photoId})});Object.assign(S,r.state);id('return-dialog').close();drawAll();toast('Return assessment saved to the audit trail.')}catch(e){error('return-error',e.message)}finally{b.disabled=false}}
async function saveCalibration(ev){ev.preventDefault();clearErr('cal-error');let b=$('button[type=submit]',ev.currentTarget);b.disabled=true;try{let r=await api('/api/calibration',{method:'POST',body:JSON.stringify({toolId:id('cal-tool-id').value,certificate:id('cal-cert').value.trim(),dueDate:id('cal-due').value})});Object.assign(S,r.state);id('calibration-dialog').close();drawAll();toast('Calibration record saved.')}catch(e){error('cal-error',e.message)}finally{b.disabled=false}}
async function bulkCalibrationSubmit(ev){ev.preventDefault();clearErr('bulk-calibration-error');if(!id('bulk-calibration-confirm').checked)return error('bulk-calibration-error','Confirm the due date applies to every item before continuing.');let b=$('button[type=submit]',ev.currentTarget);b.disabled=true;b.textContent='Saving all…';try{let r=await api('/api/calibration/bulk',{method:'POST',body:JSON.stringify({confirmed:true,dueDate:'2027-12-30'})});Object.assign(S,r.state);id('bulk-calibration-dialog').close();drawAll();toast(`Calibration saved for ${r.updatedCount} items. ${r.generatedCount} internal references generated.`)}catch(e){error('bulk-calibration-error',e.message)}finally{b.disabled=false;b.textContent='Apply to all gauges'}}
async function registerEquipmentSubmit(ev){ev.preventDefault();clearErr('equipment-register-error');const f=ev.currentTarget,b=$('button[type=submit]',f),existingId=id('equipment-record-id').value,editing=!!existingId;const payload={id:existingId,categoryGroup:id('equipment-category-group').value,unit:id('equipment-unit').value.trim()};for(const field of equipmentFields)payload[field]=id(equipmentFieldId(field)).value.trim();if(!editing&&CATEGORY_ID_PREFIXES[payload.categoryGroup])payload.gaugeToolId='';b.disabled=true;b.textContent=editing?'Saving…':'Registering…';try{const r=await api(editing?'/api/inventory/update':'/api/inventory/register',{method:'POST',body:JSON.stringify(payload)}),at=S.inventory.findIndex(t=>t.id===r.item.id);if(at>=0)S.inventory[at]=r.item;else S.inventory.push(r.item);Object.assign(S,r.state);id('register-equipment-dialog').close();f.reset();showOther=true;selectedOtherType=r.item.categoryGroup;id('inventory-search').value='';drawAll();go('inventory');toast(editing?'Equipment register updated.':`Registered ${r.item.gaugeToolId||r.item.id}. Add its calibration record before borrowing.`)}catch(e){error('equipment-register-error',e.message)}finally{b.disabled=false;b.textContent=editing?'Save register details':'Register equipment'}}function openUserEditor(username=''){id('user-form').reset();clearErr('user-error');id('user-original-username').value=username;let user=S.accounts.find(a=>a.username===username);id('user-dialog-title').textContent=user?'Edit user account':'Add user account';id('user-save-button').textContent=user?'Save changes':'Create account';id('user-password').required=!user;id('user-password-help').textContent=user?'Leave blank to keep the current password. Enter at least 12 characters to reset it.':'At least 12 characters. Required for new accounts.';id('user-name').value=user?.name||'';id('user-username').value=user?.username||'';id('user-role').value=user?.role||'staff';id('user-role').disabled=!!user&&user.username===currentUser.username;id('user-username').disabled=!!user&&user.username===currentUser.username;id('user-dialog').showModal()}
async function userSubmit(ev){ev.preventDefault();clearErr('user-error');const originalUsername=id('user-original-username').value,payload={username:originalUsername,name:id('user-name').value.trim(),newUsername:id('user-username').value.trim(),role:id('user-role').value,password:id('user-password').value};if(!originalUsername){payload.username=payload.newUsername;delete payload.newUsername}if(payload.password&&payload.password.length<12)return error('user-error','Use a password with at least 12 characters.');const button=id('user-save-button');button.disabled=true;try{const r=await api(originalUsername?'/api/users/update':'/api/users',{method:'POST',body:JSON.stringify(payload)});S.accounts=r.accounts;S.staff=r.staff;id('user-dialog').close();drawAll();toast(originalUsername?'Account updated.':'User account created.')}catch(e){error('user-error',e.message)}finally{button.disabled=false}}
async function toggleUser(username){const a=S.accounts.find(x=>x.username===username);if(!a)return;const action=a.active?'disable':'enable';if(!confirm(`${action==='disable'?'Disable':'Enable'} ${a.name}'s account?`))return;try{const r=await api('/api/users/toggle',{method:'POST',body:JSON.stringify({username,active:!a.active})});S.accounts=r.accounts;S.staff=r.staff;drawAll();toast(`Account ${a.active?'disabled':'enabled'}.`)}catch(e){toast(e.message)}}
async function deleteUser(username){const a=S.accounts.find(x=>x.username===username);if(!a||!confirm(`Delete ${a.name}'s account? Historical audit and loan records will remain.`))return;try{const r=await api('/api/users/delete',{method:'POST',body:JSON.stringify({username})});S.accounts=r.accounts;S.staff=r.staff;drawAll();toast('Account deleted. Historical records remain.')}catch(e){toast(e.message)}}
async function showPhoto(pid,caption){try{let r=await fetch(`/api/photos/${encodeURIComponent(pid)}`);if(!r.ok)throw Error('Photo not found on server.');if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=URL.createObjectURL(await r.blob());id('photo-large').src=photoUrl;id('photo-caption').textContent=caption||'Evidence photo';id('photo-dialog').showModal()}catch(e){toast(e.message)}}
async function exportData(){try{let x=await api('/api/export'),a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(x,null,2)],{type:'application/json'}));a.href=u;a.download=`equipment-gauge-borrow-return-backup-${today()}.json`;a.click();URL.revokeObjectURL(u);toast('Records exported. Copy data/photos separately for image backup.')}catch(e){toast(e.message)}}
function checkNotifications(){if(!('Notification'in window)||Notification.permission!=='granted')return;let seen=JSON.parse(localStorage.getItem('gauge-alerts')||'{}'),dirty=false;for(let l of S.loans.filter(active)){let s=status(l);if(!['OVERDUE','DUE SOON'].includes(s))continue;let k=`${l.loanId}:${s}:${today()}`;if(seen[k])continue;new Notification(s==='OVERDUE'?'Gauge return overdue':'Gauge return due soon',{body:`${l.staff} · ${l.toolId} / ${l.gaugeSize} · JO ${l.jobOrder}`,tag:k});seen[k]=Date.now();dirty=true}if(dirty)localStorage.setItem('gauge-alerts',JSON.stringify(Object.fromEntries(Object.entries(seen).slice(-1000))))}
async function enableAlerts(){if(!('Notification'in window)){toast('Browser notifications are unavailable. In-app status alerts remain active.');return}try{let p=await Notification.requestPermission();if(p==='granted'){toast('Browser alerts enabled while the app is open.');checkNotifications()}else toast('Permission not granted. In-app alerts remain active.')}catch{toast('Browser notifications require a secure connection. In-app alerts remain active.')}}
async function refresh(){if(!currentUser)return;try{Object.assign(S,await api('/api/bootstrap'));drawAll()}catch(e){if(e.message==='Sign in is required.'){currentUser=null;showLogin();return}if(!id('server-error'))id('main-content').insertAdjacentHTML('afterbegin',`<div class="callout" id="server-error"><strong>Server unavailable</strong><span>${esc(e.message)} Start the app using <code>node server.js</code>, then refresh.</span></div>`)}}
